-- Real PostgreSQL/RLS/accounting engine. Synthetic fixtures are transactionally rolled back.
BEGIN;
DO $$
DECLARE u1 uuid:=gen_random_uuid();u2 uuid:=gen_random_uuid();u3 uuid:=gen_random_uuid();c1 uuid:=gen_random_uuid();c2 uuid:=gen_random_uuid();
BEGIN
 INSERT INTO auth.users(id,email,raw_user_meta_data) VALUES(u1,'report-test-'||u1||'@example.invalid','{}'),(u2,'report-test-'||u2||'@example.invalid','{}'),(u3,'report-test-'||u3||'@example.invalid','{}');
 INSERT INTO auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) VALUES(gen_random_uuid(),u1,'totp','verified',now(),now());
 INSERT INTO public.companies(id,name,country_code,base_currency,fiscal_year_end_month,fiscal_year_end_day,timezone,created_by) VALUES(c1,'Reporting isolated A','GB','GBP',12,31,'UTC',u1),(c2,'Reporting isolated B','GB','GBP',3,31,'UTC',u3);
 PERFORM set_config('linkbooks.trusted','on',true);
 INSERT INTO public.company_members(company_id,user_id,role) VALUES(c1,u1,'owner'),(c1,u2,'accountant'),(c2,u3,'owner') ON CONFLICT(company_id,user_id) DO NOTHING;
 PERFORM public.seed_default_chart_of_accounts(c1);
 INSERT INTO public.accounting_periods(company_id,name,start_date,end_date,status) VALUES(c1,'Reporting fixture financial year','2026-01-01','2026-12-31','open');
 INSERT INTO public.bank_accounts(company_id,name,currency_code,gl_account_id) SELECT c1,'Fixture bank','GBP',id FROM public.accounts WHERE company_id=c1 AND code='1000';
 PERFORM set_config('linkbooks.trusted','off',true);
 PERFORM set_config('test.rep_u1',u1::text,true);PERFORM set_config('test.rep_u2',u2::text,true);PERFORM set_config('test.rep_u3',u3::text,true);PERFORM set_config('test.rep_c1',c1::text,true);PERFORM set_config('test.rep_c2',c2::text,true);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u1,'aal','aal2','role','authenticated','iat',extract(epoch from now()))::text,true);
END $$;
SET LOCAL ROLE authenticated;
DO $$
DECLARE c uuid:=current_setting('test.rep_c1')::uuid;foreign_c uuid:=current_setting('test.rep_c2')::uuid;u1 uuid:=current_setting('test.rep_u1')::uuid;u2 uuid:=current_setting('test.rep_u2')::uuid;u3 uuid:=current_setting('test.rep_u3')::uuid;
 visit uuid:=gen_random_uuid();model uuid;v uuid;p uuid;j uuid;bank uuid;rev uuid;expense uuid;f jsonb;old_snapshot jsonb;ver integer;outcome bigint;job uuid; schedule uuid;
BEGIN
 SELECT id INTO bank FROM public.accounts WHERE company_id=c AND code='1000';SELECT id INTO rev FROM public.accounts WHERE company_id=c AND code='4000';SELECT id INTO expense FROM public.accounts WHERE company_id=c AND code='6000';
 j:=public.post_journal(jsonb_build_object('company_id',c,'journal_date','2026-10-01','currency_code','GBP','source_type','manual','idempotency_key','report-fixture:'||gen_random_uuid(),'lines',jsonb_build_array(jsonb_build_object('account_id',bank,'debit_minor',15000,'credit_minor',0),jsonb_build_object('account_id',rev,'debit_minor',0,'credit_minor',15000))));
 PERFORM public.post_journal(jsonb_build_object('company_id',c,'journal_date','2026-10-02','currency_code','GBP','source_type','manual','idempotency_key','report-fixture:'||gen_random_uuid(),'lines',jsonb_build_array(jsonb_build_object('account_id',expense,'debit_minor',4000,'credit_minor',0),jsonb_build_object('account_id',bank,'debit_minor',0,'credit_minor',4000))));
 -- Exact filtering against posted journals, not synthetic client-side aggregates.
 IF (SELECT sum(credit_minor) FROM public.report_filtered_balances(c,'2026-10-01','2026-10-31','{"logic":"and","clauses":[{"field":"account_type","op":"eq","values":["income"]}]}'))<>15000 THEN RAISE EXCEPTION 'Income line filter wrong';END IF;
 IF (SELECT count(*) FROM public.report_filtered_balances(c,'2026-10-01','2026-10-31','{"logic":"or","clauses":[{"field":"account_type","op":"eq","values":["income"]},{"field":"account_type","op":"eq","values":["expense"]}]}'))<>2 THEN RAISE EXCEPTION 'OR filters wrong';END IF;
 IF (SELECT count(*) FROM public.report_filtered_balances(c,'2026-10-01','2026-10-31','{"logic":"and","clauses":[{"field":"account_code","op":"starts_with","values":["4"]},{"field":"credit","op":"between","values":["149.99","150.00"]},{"field":"currency","op":"eq","values":["gbp"]},{"field":"journal_date","op":"eq","values":["2026-10-01"]}]}'))<>1 THEN RAISE EXCEPTION 'AND/date/exact base-major amount filters wrong';END IF;
 IF EXISTS(SELECT 1 FROM public.report_filtered_balances(c,'2026-10-01','2026-10-31','{"logic":"and","clauses":[{"field":"memo","op":"contains","values":["%"]}]}')) THEN RAISE EXCEPTION 'Literal percent treated as wildcard';END IF;
 IF NOT private.report_filters_match('{"memo":"A_100% literal","debit":"9007199254740993.01"}','{"logic":"and","clauses":[{"field":"memo","op":"contains","values":["_100%"]},{"field":"debit","op":"gt","values":["9007199254740993.00"]}]}') THEN RAISE EXCEPTION 'Literal or exact-decimal comparison wrong';END IF;
 IF private.report_filters_match('{"memo":null}','{"logic":"and","clauses":[{"field":"memo","op":"neq","values":["x"]}]}') OR NOT private.report_filters_match('{"memo":null}','{"logic":"and","clauses":[{"field":"memo","op":"empty","values":[]}]}') THEN RAISE EXCEPTION 'Missing value filter semantics wrong';END IF;
 BEGIN PERFORM public.report_filtered_balances(c,'2026-10-01','2026-10-31','{"logic":"or","clauses":[{"field":"status","op":"eq","values":["posted"]},{"field":"credit","op":"between","values":["200","100"]}]}');RAISE EXCEPTION 'TEST: invalid second OR condition accepted';EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'TEST:%' THEN RAISE;END IF;END;
 BEGIN PERFORM public.report_filtered_balances(foreign_c,'2026-10-01','2026-10-31','{"logic":"and","clauses":[]}');RAISE EXCEPTION 'TEST: foreign filtered report accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 f:=public.capture_custom_report_facts(c,'2026-10-01','2026-10-31','{"columns":[{"id":"current","mode":"period"}],"filters":{"logic":"and","clauses":[{"field":"account_type","op":"in","values":["income"]}]}}');
 IF jsonb_array_length(f->'customColumns'->0->'balances')<>1 OR f->'customColumns'->0->'balances'->0->>'credit_minor'<>'15000' OR f->'appliedFilters'->'clauses'->0->>'field'<>'account_type' THEN RAISE EXCEPTION 'Custom fact filter or provenance wrong';END IF;
 IF has_function_privilege('anon','public.report_filtered_balances(uuid,date,date,jsonb)','EXECUTE') THEN RAISE EXCEPTION 'Anonymous filtering allowed';END IF;
 f:=public.capture_reporting_facts(c,'2026-10-01','2026-10-31');
 f:=public.capture_reporting_facts(c,'2026-10-01','2026-10-31');
 IF f->>'fyStart'<>'2026-01-01' THEN RAISE EXCEPTION 'Financial year wrong';END IF;
 SELECT (value->>'credit_minor')::bigint-(value->>'debit_minor')::bigint INTO outcome FROM jsonb_array_elements(f->'period') WHERE value->>'account_id'=rev::text;
 IF outcome<>15000 THEN RAISE EXCEPTION 'Revenue does not equal independently expected posted revenue';END IF;
 SELECT sum((value->>'debit_minor')::bigint-(value->>'credit_minor')::bigint) INTO outcome FROM jsonb_array_elements(f->'period');IF outcome<>0 THEN RAISE EXCEPTION 'Trial balance does not balance';END IF;
 IF (f->'cash'->0->>'closing_minor')::bigint<>11000 THEN RAISE EXCEPTION 'Cash closing does not match posted movements';END IF;
 f:=public.capture_custom_report_facts(c,'2026-10-01','2026-10-31',jsonb_build_object('columns',jsonb_build_array(jsonb_build_object('id','current','mode','period'),jsonb_build_object('id','double','mode','calculated','formula','[current]*2'))));
 IF jsonb_array_length(f->'customColumns')<>2 OR f->'customColumns'->1->'balances'<>'[]'::jsonb THEN RAISE EXCEPTION 'Calculated column accepted independently supplied financial facts';END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(f->'customColumns'->0->'balances') b WHERE b->>'account_id'=rev::text AND (b->>'credit_minor')::bigint=15000) THEN RAISE EXCEPTION 'Custom actual column disagrees with posted ledger';END IF;
 IF NOT public.record_report_open(c,'profit-and-loss',NULL,visit,'2026-10-01','2026-10-31') THEN RAISE EXCEPTION 'Report open was not persisted';END IF;
 IF public.record_report_open(c,'profit-and-loss',NULL,visit,'2026-10-01','2026-10-31') THEN RAISE EXCEPTION 'Retried report open duplicated usage';END IF;
 PERFORM public.record_report_open(c,'profit-and-loss',NULL,gen_random_uuid(),'2026-11-01','2026-11-30');
 IF (public.get_report_activity(c)->'recent'->0->>'opens')::int<>2 OR public.get_report_activity(c)->'recent'->0->>'from'<>'2026-11-01' THEN RAISE EXCEPTION 'Recent/frequent report activity is not accurate';END IF;
 visit:=gen_random_uuid();
 PERFORM public.record_report_open(c,'general-ledger',NULL,visit,'2026-10-01','2026-10-31',jsonb_build_object('account',bank,'columns','month'));
 IF public.record_report_open(c,'general-ledger',NULL,visit,'2026-10-01','2026-10-31','{}') THEN RAISE EXCEPTION 'Retried activity overwrote its filter context';END IF;
 IF public.get_report_activity(c)->'recent'->0->'search'->>'account'<>bank::text THEN RAISE EXCEPTION 'Recent GL report lost selected account';END IF;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u2,'aal','aal2','role','authenticated')::text,true);
 IF jsonb_array_length(public.get_report_activity(c)->'recent')<>0 OR EXISTS(SELECT 1 FROM public.report_open_events WHERE company_id=c) THEN RAISE EXCEPTION 'Another member can see private report activity';END IF;
 BEGIN PERFORM public.record_report_open(foreign_c,'profit-and-loss',NULL,gen_random_uuid(),'2026-10-01','2026-10-31');RAISE EXCEPTION 'TEST: foreign activity write accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 IF has_table_privilege('authenticated','public.report_open_events','INSERT') THEN RAISE EXCEPTION 'Activity actor can be forged by direct insert';END IF;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u1,'aal','aal2','role','authenticated')::text,true);
 INSERT INTO public.report_saved_views(company_id,user_id,report_id,name,config) VALUES(c,u1,'profit-and-loss','Fixture custom report','{"columns":"prior_year"}') RETURNING id INTO v;
 IF (SELECT modified_by FROM public.report_saved_views WHERE id=v)<>u1 THEN RAISE EXCEPTION 'Modifier metadata missing';END IF;
 INSERT INTO public.report_saved_views(company_id,user_id,report_id,name,config) SELECT c,u1,'profit-and-loss','Search fixture '||n,'{}' FROM generate_series(1,1000) n;
 IF (SELECT count(*) FROM public.report_saved_views WHERE company_id=c AND name LIKE 'Search fixture %')<>1000 THEN RAISE EXCEPTION 'Saved reports truncated';END IF;
 UPDATE public.report_saved_views SET name='Renamed fixture',is_favourite=true,config='{"_library":{"archived":true,"template":true}}' WHERE id=v;
 IF NOT (SELECT is_favourite FROM public.report_saved_views WHERE id=v) THEN RAISE EXCEPTION 'Favourite not persisted';END IF;
 UPDATE public.report_saved_views SET config='{"_library":{"archived":false,"template":true}}' WHERE id=v;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u2,'aal','aal2','role','authenticated')::text,true);
 IF EXISTS(SELECT 1 FROM public.report_saved_views WHERE id=v) THEN RAISE EXCEPTION 'Private view leaked';END IF;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u1,'aal','aal2','role','authenticated')::text,true);
 PERFORM public.set_report_access(v,'selected',jsonb_build_array(jsonb_build_object('userId',u2,'access','view')),NULL);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u2,'aal','aal2','role','authenticated')::text,true);
 IF NOT EXISTS(SELECT 1 FROM public.report_saved_views WHERE id=v) THEN RAISE EXCEPTION 'Granted reader cannot see report';END IF;
 PERFORM public.record_report_open(c,'profit-and-loss',v,gen_random_uuid(),'2026-10-01','2026-10-31');
 UPDATE public.report_saved_views SET name='Forbidden rename' WHERE id=v;GET DIAGNOSTICS ver=ROW_COUNT;IF ver<>0 THEN RAISE EXCEPTION 'Viewer can edit';END IF;
 BEGIN PERFORM public.set_report_access(v,'company','[]',NULL);RAISE EXCEPTION 'TEST: nonowner share accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u1,'aal','aal2','role','authenticated')::text,true);
 PERFORM public.set_report_access(v,'selected',jsonb_build_array(jsonb_build_object('userId',u2,'access','edit')),NULL);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u2,'aal','aal2','role','authenticated')::text,true);
 UPDATE public.report_saved_views SET name='Editor saved' WHERE id=v;
 IF (SELECT modified_by FROM public.report_saved_views WHERE id=v)<>u2 THEN RAISE EXCEPTION 'Actual modifier was not recorded';END IF;
 BEGIN UPDATE public.report_saved_views SET user_id=u2 WHERE id=v;RAISE EXCEPTION 'TEST: ownership reassigned';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u1,'aal','aal2','role','authenticated')::text,true);
 PERFORM public.set_report_access(v,'private','[]',NULL);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u2,'aal','aal2','role','authenticated')::text,true);
 IF EXISTS(SELECT 1 FROM public.report_saved_views WHERE id=v) THEN RAISE EXCEPTION 'Revocation ineffective';END IF;
 IF jsonb_array_length(public.get_report_activity(c)->'recent')<>0 THEN RAISE EXCEPTION 'Revoked shared report still leaks its activity title';END IF;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u3,'aal','aal2','role','authenticated')::text,true);
 IF EXISTS(SELECT 1 FROM public.report_saved_views WHERE company_id=c) THEN RAISE EXCEPTION 'Cross-tenant saved report read';END IF;
 BEGIN PERFORM public.capture_reporting_facts(c,'2026-10-01','2026-10-31');RAISE EXCEPTION 'TEST: cross-tenant capture accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u1,'aal','aal2','role','authenticated')::text,true);
 BEGIN PERFORM public.set_report_access(v,'selected',jsonb_build_array(jsonb_build_object('userId',u3,'access','view')),NULL);RAISE EXCEPTION 'TEST: foreign recipient accepted';EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'Recipients must%' THEN RAISE;END IF;END;
 INSERT INTO public.report_models(company_id,owner_id,name,kind,config) VALUES(c,u1,'Dashboard fixture','dashboard','{"widgets":["revenue"]}') RETURNING id INTO model;
 UPDATE public.report_models SET name='Updated dashboard',config='{"widgets":["net_profit"]}' WHERE id=model AND version=1;
 IF (SELECT version FROM public.report_models WHERE id=model)<>2 OR NOT EXISTS(SELECT 1 FROM public.report_model_versions WHERE model_id=model AND version=1 AND name='Dashboard fixture') THEN RAISE EXCEPTION 'Model revision lost';END IF;
 UPDATE public.report_models SET name='Stale overwrite' WHERE id=model AND version=1;GET DIAGNOSTICS ver=ROW_COUNT;IF ver<>0 THEN RAISE EXCEPTION 'Stale model overwrite accepted';END IF;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u1,'aal','aal1','role','authenticated')::text,true);
 IF EXISTS(SELECT 1 FROM public.report_models WHERE id=model) THEN RAISE EXCEPTION 'MFA requirement bypassed';END IF;
 BEGIN PERFORM public.capture_reporting_facts(c,'2026-10-01','2026-10-31');RAISE EXCEPTION 'TEST: MFA capture bypass';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u1,'aal','aal2','role','authenticated')::text,true);
 p:=public.save_report_pack(c,jsonb_build_object('name','October management','from','2026-10-01','to','2026-10-31','reviewerId',u2,'config',jsonb_build_object('reports',jsonb_build_array('profit-and-loss','balance-sheet','cash-summary'),'commentary','Independently reviewed fixture')));
 PERFORM public.transition_report_pack(p,1,'submit','Prepared from posted journals');
 SELECT snapshot INTO old_snapshot FROM public.report_packs WHERE id=p;
 BEGIN PERFORM public.transition_report_pack(p,2,'approve','Self approve');RAISE EXCEPTION 'TEST: self approval accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.transition_report_pack(p,1,'start','Stale');RAISE EXCEPTION 'TEST: stale workflow accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;
 BEGIN UPDATE public.report_packs SET snapshot='{}' WHERE id=p;RAISE EXCEPTION 'TEST: client financial facts accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u2,'aal','aal2','role','authenticated')::text,true);
 PERFORM public.transition_report_pack(p,2,'approve','Reviewed fixture balance and cash');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u1,'aal','aal2','role','authenticated')::text,true);
 PERFORM public.transition_report_pack(p,3,'publish','Approved pack issued');
 PERFORM public.post_journal(jsonb_build_object('company_id',c,'journal_date','2026-10-03','currency_code','GBP','source_type','manual','idempotency_key','report-fixture:'||gen_random_uuid(),'lines',jsonb_build_array(jsonb_build_object('account_id',bank,'debit_minor',1000,'credit_minor',0),jsonb_build_object('account_id',rev,'debit_minor',0,'credit_minor',1000))));
 IF (SELECT snapshot FROM public.report_packs WHERE id=p) IS DISTINCT FROM old_snapshot THEN RAISE EXCEPTION 'Published snapshot changed after ledger posting';END IF;
 BEGIN PERFORM public.save_report_pack(c,jsonb_build_object('id',p,'version',4,'name','Tampered','from','2026-10-01','to','2026-10-31','config',jsonb_build_object('reports',jsonb_build_array('profit-and-loss'))));RAISE EXCEPTION 'TEST: published pack editable';EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE 'This pack is locked%' THEN RAISE;END IF;END;
 j:=public.save_report_pack(c,jsonb_build_object('name','Rejection workflow','from','2026-10-01','to','2026-10-31','reviewerId',u2,'config',jsonb_build_object('reports',jsonb_build_array('profit-and-loss'))));
 PERFORM public.transition_report_pack(j,1,'start','Preparation started');
 PERFORM public.transition_report_pack(j,2,'submit','Ready for review');
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u2,'aal','aal2','role','authenticated')::text,true);
 INSERT INTO public.report_comments(pack_id,company_id,author_id,body) VALUES(j,c,u2,'Please clarify expense movement');
 PERFORM public.transition_report_pack(j,3,'request_changes','Explain expense movement');
 IF (SELECT status FROM public.report_packs WHERE id=j)<>'review_required' OR NOT EXISTS(SELECT 1 FROM public.report_comments WHERE pack_id=j AND author_id=u2 AND body='Please clarify expense movement') THEN RAISE EXCEPTION 'Reviewer feedback or attribution lost';END IF;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u1,'aal','aal2','role','authenticated')::text,true);
 job:=public.queue_report_delivery(c,jsonb_build_object('packId',p,'recipients',jsonb_build_array('fixture@example.invalid'),'subject','No send: transactional outbox test'));
 IF (SELECT status FROM public.report_deliveries WHERE id=job)<>'queued' THEN RAISE EXCEPTION 'Delivery status fabricated';END IF;
 IF (SELECT status FROM public.report_packs WHERE id=p)<>'published' THEN RAISE EXCEPTION 'Queued job falsely marked delivered';END IF;
 schedule:=public.save_report_schedule(c,jsonb_build_object('packId',p,'recipients',jsonb_build_array('fixture@example.invalid'),'subject','Schedule fixture','recurrence','monthly','period','previous_month','timezone','Asia/Kolkata','nextRunAt',now()-interval '1 minute','enabled',true));
 PERFORM public.transition_report_pack(p,4,'archive','Archive after issue');PERFORM public.transition_report_pack(p,5,'restore','Restore original publication');
 IF (SELECT status FROM public.report_packs WHERE id=p)<>'published' THEN RAISE EXCEPTION 'Restore loses lifecycle state';END IF;
 IF (public.report_pack_counts(c)->>'published')::int<>1 THEN RAISE EXCEPTION 'Pack count does not include persisted publication';END IF;
 IF public.report_pack_integrity(p) IS DISTINCT FROM true THEN RAISE EXCEPTION 'Snapshot hash invalid';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.audit_events WHERE company_id=c AND action='report.pack_publish') THEN RAISE EXCEPTION 'Lifecycle audit missing';END IF;
 IF has_function_privilege('anon','public.capture_reporting_facts(uuid,date,date)','EXECUTE') OR has_function_privilege('authenticated','public.claim_report_deliveries(integer)','EXECUTE') THEN RAISE EXCEPTION 'Privileged worker exposed';END IF;
 PERFORM set_config('test.rep_job',job::text,true);PERFORM set_config('test.rep_schedule',schedule::text,true);PERFORM set_config('test.rep_pack',p::text,true);
END $$;
RESET ROLE;
SELECT public.enqueue_due_report_schedules(now());
DO $$
DECLARE j public.report_deliveries;job uuid:=current_setting('test.rep_job')::uuid;p uuid:=current_setting('test.rep_pack')::uuid;
BEGIN
 IF (SELECT count(*) FROM public.report_deliveries WHERE schedule_id=current_setting('test.rep_schedule')::uuid)<>1 THEN RAISE EXCEPTION 'Schedule did not enqueue once';END IF;
 PERFORM public.enqueue_due_report_schedules(now());
 IF (SELECT count(*) FROM public.report_deliveries WHERE schedule_id=current_setting('test.rep_schedule')::uuid)<>1 THEN RAISE EXCEPTION 'Duplicate schedule execution';END IF;
 FOR j IN SELECT * FROM public.claim_report_deliveries(10) LOOP
  IF j.id=job THEN PERFORM public.finish_report_delivery(j.id,j.attempts,'fixture-provider-id',NULL);END IF;
 END LOOP;
 IF (SELECT status FROM public.report_deliveries WHERE id=job)<>'accepted' THEN RAISE EXCEPTION 'Provider acceptance not recorded';END IF;
 IF (SELECT status FROM public.report_packs WHERE id=p)<>'published' THEN RAISE EXCEPTION 'Acceptance incorrectly treated as confirmed delivery';END IF;
 INSERT INTO public.report_deliveries(company_id,owner_id,pack_id,recipients,subject,message,facts,definition,status,provider_id)
 SELECT d.company_id,d.owner_id,d.pack_id,d.recipients,d.subject,d.message,d.facts,d.definition,'accepted','fixture-poll-'||n
 FROM public.report_deliveries d CROSS JOIN generate_series(1,26) n WHERE d.id=job;
 IF (SELECT count(*) FROM public.claim_report_delivery_confirmations(25))<>25 THEN RAISE EXCEPTION 'Confirmation polling did not claim first page';END IF;
 IF (SELECT count(*) FROM public.claim_report_delivery_confirmations(25))<>2 THEN RAISE EXCEPTION 'Old pending confirmations starve later messages';END IF;
 IF EXISTS(SELECT 1 FROM public.claim_report_delivery_confirmations(25)) THEN RAISE EXCEPTION 'Confirmation claim ignored cooldown';END IF;
 IF has_function_privilege('authenticated','public.claim_report_delivery_confirmations(integer)','EXECUTE') THEN RAISE EXCEPTION 'Application user can claim provider events';END IF;
 PERFORM public.confirm_report_delivery('fixture-provider-id',true,NULL);
 IF (SELECT status FROM public.report_packs WHERE id=p)<>'delivered' THEN RAISE EXCEPTION 'Confirmed delivery not recorded';END IF;
END $$;
DO $$ BEGIN
 IF private.next_reporting_run('2026-01-31 09:00Z','2026-02-28 10:00Z','monthly','UTC')<>'2026-03-31 09:00Z'::timestamptz THEN RAISE EXCEPTION 'Month-end recurrence drift';END IF;
 IF private.next_reporting_run('2024-02-29 09:00Z','2027-03-01 10:00Z','yearly','UTC')<>'2028-02-29 09:00Z'::timestamptz THEN RAISE EXCEPTION 'Leap-year recurrence drift';END IF;
END $$;
-- Entitlement defaults, tenant-role denial, frozen writes and access revocation.
DO $$ DECLARE c uuid:=current_setting('test.rep_c1')::uuid;v uuid; BEGIN
 INSERT INTO public.report_saved_views(company_id,user_id,report_id,name,config) VALUES(c,current_setting('test.rep_u1')::uuid,'profit-and-loss','Frozen revocation fixture','{}') RETURNING id INTO v;
 PERFORM public.set_report_access(v,'selected',jsonb_build_array(jsonb_build_object('userId',current_setting('test.rep_u2'),'access','view')),NULL);
 PERFORM set_config('test.rep_frozen_view',v::text,true);
 PERFORM set_config('test.rep_frozen_delivery',public.queue_report_delivery(c,jsonb_build_object('packId',current_setting('test.rep_pack'),'recipients',jsonb_build_array('fixture@example.invalid'),'subject','No send: entitlement freeze fixture'))::text,true);
 IF public.get_reporting_feature_access(c)->>'allowed' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Included reporting suite is unavailable';END IF;
 INSERT INTO public.entitlement_overrides(feature_key,scope,scope_id,source,effect,reason) VALUES('reporting','business',c,'revoke','deny','Transactional reporting feature denial test');
END $$;
SET LOCAL ROLE authenticated;
DO $$ DECLARE c uuid:=current_setting('test.rep_c1')::uuid;v uuid:=current_setting('test.rep_frozen_view')::uuid; BEGIN
 IF public.record_report_open(c,'profit-and-loss',NULL,gen_random_uuid(),'2026-10-01','2026-10-31') THEN RAISE EXCEPTION 'Frozen reporting still records new activity';END IF;
 IF public.get_reporting_feature_access(c)->>'source'<>'revoke' OR public.get_reporting_feature_access(c)->>'allowed'<>'false' THEN RAISE EXCEPTION 'Authoritative reporting denial missing';END IF;
 BEGIN PERFORM public.capture_reporting_facts(c,'2026-10-01','2026-10-31');RAISE EXCEPTION 'TEST: frozen reporting capture accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN INSERT INTO public.report_models(company_id,owner_id,name,kind,config) VALUES(c,auth.uid(),'Forbidden frozen model','dashboard','{}');RAISE EXCEPTION 'TEST: direct frozen model write accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN UPDATE public.report_saved_views SET name='Forbidden frozen edit' WHERE id=v;RAISE EXCEPTION 'TEST: frozen edit accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.platform_set_entitlement('reporting','business',c,NULL,'grant','allow',NULL,NULL,'Tenant cannot self-authorize','');RAISE EXCEPTION 'TEST: tenant can self-authorize a platform feature';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 IF NOT EXISTS(SELECT 1 FROM public.report_packs WHERE id=current_setting('test.rep_pack')::uuid AND snapshot IS NOT NULL) THEN RAISE EXCEPTION 'Feature removal lost approved history';END IF;
 PERFORM public.set_report_access(v,'private','[]',NULL);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.rep_u2'),'aal','aal2','role','authenticated')::text,true);
 IF EXISTS(SELECT 1 FROM public.report_saved_views WHERE id=v) THEN RAISE EXCEPTION 'Sharing cannot be revoked while feature is frozen';END IF;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.rep_u1'),'aal','aal2','role','authenticated')::text,true);
 IF has_function_privilege('anon','public.get_reporting_feature_access(uuid)','EXECUTE') THEN RAISE EXCEPTION 'Feature decision API exposed anonymously';END IF;
END $$;
RESET ROLE;
DO $$ DECLARE c uuid:=current_setting('test.rep_c1')::uuid;BEGIN
 PERFORM public.claim_report_deliveries(10);
 IF (SELECT status FROM public.report_deliveries WHERE id=current_setting('test.rep_frozen_delivery')::uuid)<>'cancelled' THEN RAISE EXCEPTION 'Frozen entitlement did not stop queued delivery';END IF;
 DELETE FROM public.entitlement_overrides WHERE scope='business' AND scope_id=c AND feature_key='reporting';
 INSERT INTO public.entitlement_overrides(feature_key,scope,scope_id,source,effect,reason) VALUES('accounting','business',c,'revoke','deny','Transactional reporting dependency denial test');
 IF public.get_reporting_feature_access(c)->>'dependency'<>'accounting' OR public.get_reporting_feature_access(c)->>'allowed'<>'false' THEN RAISE EXCEPTION 'Reporting dependency is not enforced';END IF;
END $$;
ROLLBACK;
SELECT 'reporting_ecosystem: CRUD/1000 reports/sharing/revocation/tenant isolation/snapshots/independent approval/audit/outbox/schedule assertions passed; every fixture rolled back; no email sent' AS result;
